import { describe, expect, it } from 'vitest';

import { packInt, packString } from '../../src/format/flatpack';
import { FlatPackWriter } from '../../src/format/writer';
import { concat, toHex } from '../helpers/bytes';

describe('FlatPackWriter', () => {
  it('concatenates fields exactly like manual packing', () => {
    const writer = new FlatPackWriter();
    writer.writeInt(2).writeString('test').writeString('bYxwbP1r');
    const expected = concat(packInt(2), packString('test'), packString('bYxwbP1r'));
    expect(toHex(writer.toBytes())).toBe(toHex(expected));
  });

  it('produces the known flat-pack prefix of scripts/test.db', () => {
    const writer = new FlatPackWriter();
    writer.writeInt(2).writeString('').writeString('');
    // "00012" + "0000" + "0000"
    expect(toHex(writer.toBytes())).toBe('30303031323030303030303030');
  });

  it('appends raw bytes verbatim', () => {
    const writer = new FlatPackWriter();
    writer.writeBytes(new Uint8Array([0xaa, 0xbb])).writeString('hi');
    expect(toHex(writer.toBytes())).toBe(`aabb${toHex(packString('hi'))}`);
  });
});
